451:                 new TupleTypeInfo<>(BasicTypeInfo.INT_TYPE_INFO, BasicTypeInfo.INT_TYPE_INFO);
452: 
453:         env.fromSequence(0, NUMBER_KEYS * NUMBER_OF_EACH_KEY - 1)
454:                 .setParallelism(SOURCE_PARALLELISM)
