488:         env.fromSource(source, WatermarkStrategy.noWatermarks(), "source")
489:                 .setParallelism(SOURCE_PARALLELISM)
490:                 .slotSharingGroup("group1")
491:                 .transform("Map", typeInfo, new StubMapFunction2())
492:                 .slotSharingGroup("group2")
