448:     private StreamGraph createJobGraph(StreamExecutionEnvironment env, String jobName) {
449:         TupleTypeInfo<Tuple2<Integer, Integer>> typeInfo =
450:                 new TupleTypeInfo<>(BasicTypeInfo.INT_TYPE_INFO, BasicTypeInfo.INT_TYPE_INFO);
451: 
452:         env.fromSequence(0, NUMBER_KEYS * NUMBER_OF_EACH_KEY - 1)
453:                 .setParallelism(SOURCE_PARALLELISM)
454:                 .slotSharingGroup("group1")
455:                 .transform("SourceTail", TypeInformation.of(Long.class), new SourceTail())
456:                 .setParallelism(SOURCE_PARALLELISM)
457:                 .slotSharingGroup("group1")
458:                 .transform("Map", typeInfo, new StubMapFunction())
459:                 .slotSharingGroup("group2")
460:                 .keyBy(tuple2 -> tuple2.f0)
461:                 .sum(1)
462:                 .slotSharingGroup("group3")
463:                 .transform("Sink", TypeInformation.of(Void.class), new StubRecordSink())
464:                 .slotSharingGroup("group4");
465: 
466:         org.apache.flink.streaming.api.graph.StreamGraph streamGraph = env.getStreamGraph();
467:         streamGraph.setGlobalStreamExchangeMode(GlobalStreamExchangeMode.ALL_EDGES_BLOCKING);
468:         streamGraph.setJobType(JobType.BATCH);
469:         streamGraph.setJobName(jobName);
470:         return StreamingJobGraphGenerator.createJobGraph(streamGraph);
471:     }
