510:     /**
511:      * A stub which helps to:
512:      *
513:      * <p>1. Get source tasks' information. (Such as {@link ResultPartitionID}).
514:      *
515:      * <p>2. Manually control the execution of source task. Helps to block and unblock execution of
516:      * source task.
517:      *
518:      * <p>This operator should be chained with source operator.
519:      */
520:     private static class SourceTail extends AbstractStreamOperator<Long>
521:             implements OneInputStreamOperator<Long, Long> {
522: 
523:         public static Map<Integer, Boolean> subtaskBlocked = new ConcurrentHashMap<>();
524:         public static Map<Integer, ResultPartitionID> resultPartitions = new ConcurrentHashMap<>();
525:         public static Map<Integer, Integer> attemptIds = new ConcurrentHashMap<>();
526: 
527:         public SourceTail() {
528:             super();
529:         }
530: 
531:         @Override
532:         protected void setup(
533:                 StreamTask<?, ?> containingTask,
534:                 StreamConfig config,
535:                 Output<StreamRecord<Long>> output) {
536:             super.setup(containingTask, config, output);
537: 
538:             int subIdx = getRuntimeContext().getTaskInfo().getIndexOfThisSubtask();
539: 
540:             // attempt id ++
541:             attemptIds.compute(
542:                     subIdx,
543:                     (ignored, value) -> {
544:                         if (value == null) {
545:                             value = 0;
546:                         } else {
547:                             value += 1;
548:                         }
549:                         return value;
550:                     });
551: 
552:             // record result partition id.
553:             Environment environment = getContainingTask().getEnvironment();
554:             checkState(environment.getAllWriters().length == 1);
555:             resultPartitions.put(subIdx, environment.getAllWriters()[0].getPartitionId());
556: 
557:             // wait until unblocked.
558:             if (subtaskBlocked.containsKey(subIdx) && subtaskBlocked.get(subIdx)) {
559:                 tryWaitUntilCondition(() -> !subtaskBlocked.get(subIdx));
560:             }
561:         }
562: 
563:         @Override
564:         public void processElement(StreamRecord<Long> streamRecord) throws Exception {
565:             output.collect(streamRecord);
566:         }
567: 
568:         public static void clear() {
569:             subtaskBlocked.clear();
570:             attemptIds.clear();
571:             resultPartitions.clear();
572:         }
573: 
574:         public static void blockSubTasks(Integer... subIndices) {
575:             setSubtaskBlocked(Arrays.asList(subIndices), true, subtaskBlocked);
576:         }
577: 
578:         public static void unblockSubTasks(Integer... subIndices) {
579:             setSubtaskBlocked(Arrays.asList(subIndices), false, subtaskBlocked);
580:         }
581:     }
