359:     private StreamGraph prepareEnvAndGetJobGraph(
360:             Configuration config, boolean operatorCoordinatorsSupportsBatchSnapshot)
361:             throws Exception {
362:         flinkCluster =
363:                 TestingMiniCluster.newBuilder(getMiniClusterConfiguration(config))
364:                         .setHighAvailabilityServicesSupplier(highAvailabilityServicesSupplier)
365:                         .build();
366:         flinkCluster.start();
367: 
368:         final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
369:         env.setParallelism(-1);
370:         env.setRuntimeMode(RuntimeExecutionMode.BATCH);
371: 
372:         return operatorCoordinatorsSupportsBatchSnapshot
373:                 ? createJobGraph(env, methodName)
374:                 : createJobGraphWithUnsupportedBatchSnapshotOperatorCoordinator(env, methodName);
375:     }
