377:     private TestingMiniClusterConfiguration getMiniClusterConfiguration(Configuration config)
378:             throws IOException {
379:         // flink basic configuration.
380:         NetUtils.Port jobManagerRpcPort = NetUtils.getAvailablePort();
381:         flinkConfiguration.set(ExecutionOptions.RUNTIME_MODE, RuntimeExecutionMode.BATCH);
382:         flinkConfiguration.set(JobManagerOptions.PORT, jobManagerRpcPort.getPort());
383:         flinkConfiguration.set(JobManagerOptions.SLOT_REQUEST_TIMEOUT, Duration.ofMillis(5000L));
384:         flinkConfiguration.set(RestOptions.BIND_PORT, "0");
385:         flinkConfiguration.set(TaskManagerOptions.TOTAL_PROCESS_MEMORY, MemorySize.parse("1g"));
386:         flinkConfiguration.set(TaskManagerOptions.NETWORK_MEMORY_FRACTION, 0.4F);
387: 
388:         // adaptive batch job scheduler config.
389:         flinkConfiguration.set(
390:                 JobManagerOptions.SCHEDULER, JobManagerOptions.SchedulerType.AdaptiveBatch);
391:         flinkConfiguration.set(
392:                 BatchExecutionOptions.ADAPTIVE_AUTO_PARALLELISM_MAX_PARALLELISM,
393:                 DEFAULT_MAX_PARALLELISM);
394:         flinkConfiguration.set(
395:                 BatchExecutionOptions.ADAPTIVE_AUTO_PARALLELISM_AVG_DATA_VOLUME_PER_TASK,
396:                 MemorySize.parse("256K"));
397: 
398:         // enable jm failover.
399:         flinkConfiguration.set(BatchExecutionOptions.JOB_RECOVERY_ENABLED, true);
400:         flinkConfiguration.set(
401:                 BatchExecutionOptions.JOB_RECOVERY_SNAPSHOT_MIN_PAUSE, Duration.ZERO);
402: 
403:         // region failover config.
404:         flinkConfiguration.set(JobManagerOptions.EXECUTION_FAILOVER_STRATEGY, "region");
405:         flinkConfiguration.set(RestartStrategyOptions.RESTART_STRATEGY, "fixed-delay");
406:         flinkConfiguration.set(RestartStrategyOptions.RESTART_STRATEGY_FIXED_DELAY_ATTEMPTS, 10);
407: 
408:         // ha config, which helps to trigger jm failover.
409:         flinkConfiguration.set(HighAvailabilityOptions.HA_STORAGE_PATH, temporaryFolder.toString());
410:         highAvailabilityServices =
411:                 new EmbeddedHaServicesWithLeadershipControl(EXECUTOR_EXTENSION.getExecutor());
412:         highAvailabilityServicesSupplier = () -> highAvailabilityServices;
413: 
414:         // shuffle dir, to help trigger partitionNotFoundException
415:         flinkConfiguration.set(CoreOptions.TMP_DIRS, temporaryFolder.toString());
416: 
417:         // add user defined config
418:         flinkConfiguration.addAll(config);
419: 
420:         return TestingMiniClusterConfiguration.newBuilder()
421:                 .setConfiguration(flinkConfiguration)
422:                 .setNumTaskManagers(numTaskManagers)
423:                 .setNumSlotsPerTaskManager(numSlotsPerTaskManager)
424:                 .build();
425:     }
