767:     private void deleteOldestFileInShuffleNettyDirectory(File directory) {
768:         if (directory == null || !directory.exists() || !directory.isDirectory()) {
769:             return;
770:         }
771: 
772:         File[] matchingDirectories =
773:                 directory.listFiles(
774:                         file ->
775:                                 file.isDirectory()
776:                                         && file.getName().startsWith("flink-netty-shuffle"));
777: 
778:         if (matchingDirectories == null) {
779:             return;
780:         }
781: 
782:         List<File> files = new ArrayList<>();
783:         for (File subdirectory : matchingDirectories) {
784:             Arrays.stream(subdirectory.listFiles())
785:                     .filter(file -> file.getName().endsWith(PartitionedFile.DATA_FILE_SUFFIX))
786:                     .forEach(files::add);
787:         }
788: 
789:         if (!files.isEmpty()) {
790:             files.sort(Comparator.comparing(this::getFileCreationTime));
791:             files.get(0).delete();
792:         }
793:     }
794: 
795:     private long getFileCreationTime(File file) {
796:         try {
797:             BasicFileAttributes attrs =
798:                     Files.readAttributes(file.toPath(), BasicFileAttributes.class);
799:             return attrs.creationTime().toMillis();
800:         } catch (NoSuchFileException e) {
801:             // TaskExecutor will delete unfinished partition file asynchronously when jom failover.
802:             return Long.MAX_VALUE;
803:         } catch (IOException e) {
804:             throw new RuntimeException(e);
805:         }
806:     }
